            0%, 100% { transform: translateY(0px) scale(1) rotate(0deg); opacity: 0.6; text-shadow: 0 0 5px #bb9af7; }
            50% { transform: translateY(-6px) scale(1.15) rotate(15deg); opacity: 1; text-shadow: 0 0 15px #f7768e; }
