            0%, 100% { box-shadow: 0 0 15px rgba(247, 118, 142, 0.2), inset 0 0 10px rgba(187, 154, 247, 0.1); }
            50% { box-shadow: 0 0 25px rgba(247, 118, 142, 0.4), inset 0 0 20px rgba(187, 154, 247, 0.2); }
        }

        
        :root {
            --bg-color: transparent;
            --panel-bg: rgba(26, 27, 38, 0.85);
            --card-bg: rgba(16, 16, 24, 0.6);
            --text-main: #c0caf5;
            --text-sub: #9aa5ce;
            --color-pink: #f7768e;
            --color-purple: #bb9af7;
            --color-blue: #7aa2f7;
            --color-gold: #e0af68;
