        body {
            font-family: var(--font-sc);
            margin: 0;
            padding: 20px 10px;
            background: var(--bg-color);
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100%;
            box-sizing: border-box;
        }

        
        .mg-guide-wrapper {
            width: 100%;
            max-width: 820px;
            background: var(--panel-bg);
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-top: 1px solid rgba(247, 118, 142, 0.4);
            border-bottom: 1px solid rgba(187, 154, 247, 0.4);
            border-radius: 24px;
            padding: clamp(25px, 5vw, 40px);
            box-shadow: 0 25px 50px -12px rgba(0,0,0,0.8);
            animation: magicFadeIn 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94) both, borderGlow 4s infinite ease-in-out;
            position: relative;
            overflow: hidden;
            box-sizing: border-box;
        }

        
        .mg-guide-wrapper::before, .mg-guide-wrapper::after {
            content: ''; position: absolute; border-radius: 50%; filter: blur(60px); pointer-events: none; z-index: 0;
        }
        .mg-guide-wrapper::before {
            top: -50px; left: -50px; width: 200px; height: 200px; background: rgba(247, 118, 142, 0.15);
        }
        .mg-guide-wrapper::after {
            bottom: -50px; right: -50px; width: 250px; height: 250px; background: rgba(187, 154, 247, 0.12);
        }

        
        .header-section {
            text-align: center;
            margin-bottom: 35px;
            position: relative;
            z-index: 1;
        }

        .main-title {
            font-family: var(--font-sc);
            font-size: clamp(1.8rem, 5vw, 2.6rem);
            font-weight: 900;
            color: #fff;
            margin: 0;
            letter-spacing: 4px;
            text-shadow: 0 2px 10px rgba(0,0,0,0.8), 0 0 20px rgba(247, 118, 142, 0.6), 0 0 40px rgba(187, 154, 247, 0.4);
            position: relative;
            display: inline-flex;
            align-items: center;
            gap: 15px;
        }

        .main-title i {
            color: var(--color-pink);
            font-size: 0.8em;
            animation: starFloat 3s infinite ease-in-out;
        }

        .subtitle {
            font-family: var(--font-en);
            color: var(--color-purple);
            font-size: clamp(0.85rem, 2vw, 1rem);
            letter-spacing: 6px;
            text-transform: uppercase;
            margin-top: 8px;
            opacity: 0.8;
        }

        
        .content-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 25px;
            position: relative;
            z-index: 1;
        }

        
        .info-card {
            background: var(--card-bg);
            border: 1px solid rgba(255, 255, 255, 0.05);
            border-radius: 16px;
            padding: 25px;
            box-shadow: inset 0 0 20px rgba(0,0,0,0.5), 0 8px 20px rgba(0,0,0,0.3);
            transition: transform 0.4s ease, box-shadow 0.4s ease, border-color 0.4s ease;
            animation: cardEnter 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
            display: flex;
            flex-direction: column;
        }

        .info-card:nth-child(1) { animation-delay: 0.15s; border-top: 2px solid var(--color-blue); }
        .info-card:nth-child(2) { animation-delay: 0.3s; border-top: 2px solid var(--color-pink); }

        .info-card:hover {
            transform: translateY(-5px);
            box-shadow: inset 0 0 20px rgba(255,255,255,0.02), 0 12px 30px rgba(0,0,0,0.5);
            border-color: rgba(255,255,255,0.15);
        }

        .card-title {
            font-size: 1.3rem;
            font-weight: 700;
            margin: 0 0 20px 0;
            padding-bottom: 12px;
            border-bottom: 1px solid rgba(255, 255, 255, 0.1);
            display: flex;
            align-items: center;
            gap: 10px;
        }
        .card-title.blue { color: var(--color-blue); }
        .card-title.pink { color: var(--color-pink); }

        
        .info-list {
            list-style: none;
            padding: 0;
            margin: 0;
            display: flex;
            flex-direction: column;
            gap: 15px;
            flex-grow: 1;
        }

        .info-list li {
            color: var(--text-sub);
            font-size: 0.95rem;
            line-height: 1.6;
            display: flex;
            flex-direction: column;
            gap: 5px;
        }

        .list-header {
            display: flex;
            align-items: center;
            gap: 8px;
            font-weight: 700;
            font-size: 1.05rem;
            color: var(--text-main);
        }

        .list-header i { font-size: 1.1em; }
        .icon-check { color: #9ece6a; }
        .icon-star { color: var(--color-gold); }
        .icon-xmark { color: var(--color-pink); }

        .desc-text {
            padding-left: 28px;
            font-size: 0.85em;
            opacity: 0.8;
        }

        
        .link-group {
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
            padding-left: 28px;
            margin-top: 4px;
        }

        .discord-link {
            color: #fff;
            text-decoration: none;
            font-weight: 600;
            font-size: 0.9rem;
            padding: 6px 12px;
            border-radius: 8px;
            background: rgba(88, 101, 242, 0.2);
            border: 1px solid rgba(88, 101, 242, 0.4);
            display: inline-flex;
            align-items: center;
            gap: 6px;
            transition: all 0.3s ease;
        }

        .discord-link:hover {
            background: rgba(88, 101, 242, 0.6);
            transform: scale(1.05);
            box-shadow: 0 4px 15px rgba(88, 101, 242, 0.3);
        }

        .heart-btn {
            background: linear-gradient(135deg, rgba(247, 118, 142, 0.2), rgba(187, 154, 247, 0.2));
            border: 1px solid var(--color-pink);
            color: #fff;
            text-align: center;
            padding: 12px;
            border-radius: 12px;
            text-decoration: none;
            font-weight: 700;
            font-size: 1rem;
            margin-top: 20px;
            transition: all 0.3s ease;
            display: block;
        }

        .heart-btn:hover {
            background: linear-gradient(135deg, rgba(247, 118, 142, 0.4), rgba(187, 154, 247, 0.4));
            box-shadow: 0 0 20px rgba(247, 118, 142, 0.3);
            text-shadow: 0 0 5px #fff;
            transform: translateY(-2px);
        }

        
        .swipe-hint {
            background: rgba(247, 118, 142, 0.1);
            border-left: 4px solid var(--color-pink);
            padding: 15px;
            border-radius: 0 8px 8px 0;
            margin-bottom: 20px;
            color: var(--text-main);
            font-weight: 600;
            line-height: 1.5;
        }

        .swipe-hint i {
            color: var(--color-pink);
            margin-right: 6px;
            animation: translateX 1.5s infinite ease-in-out;
        }

        @keyframes translateX {
            0%, 100% { transform: translateX(0); }
            50% { transform: translateX(5px); }
        }

        
        .footer-sig {
            text-align: center;
            margin-top: 30px;
            font-size: 0.85rem;
            color: var(--text-sub);
            opacity: 0.6;
            font-family: var(--font-en);
            position: relative;
            z-index: 1;
        }

    </style>
