            t: '文本324 (Ultimate)',
            c: '文本338\n\n• 文本57: 文本339\n• 文本58: 文本340\n\n文本341 100% 文本342'
        } 
    };
    window.openModal = (k) => { if(TOOLTIPS[k]){ document.getElementById('m-title').innerText=TOOLTIPS[k].t; document.getElementById('m-content').innerText=TOOLTIPS[k].c; document.getElementById('info-modal').classList.add('show'); }};
    window.showMod = (t,p,s,d) => { document.getElementById('m-title').innerText=t; document.getElementById('m-content').innerHTML=`<b>文本343:</b> ${p}<br><b>文本168:</b> ${s}<br><b>文本344:</b> ${d}`; document.getElementById('info-modal').classList.add('show'); };
    window.switchTab = (tid) => { 
        const root = document.getElementById('app-container');
        root.querySelectorAll('.tab-btn').forEach(b=>b.classList.remove('active')); root.querySelectorAll('.tab-content').forEach(c=>c.classList.remove('active'));
        event.currentTarget.classList.add('active'); root.querySelector('#'+tid).classList.add('active');
    };


    const init = () => {
        const render = (d) => {
            const c = document.getElementById('app-container'); if(!c) return;
            const h = renderApp(d); const t = document.createElement('div'); t.innerHTML = h;
            const active = c.querySelector('.tab-content.active')?.id;
            if(active) { t.querySelector('.tab-content.active')?.classList.remove('active'); t.querySelector('.tab-btn.active')?.classList.remove('active'); t.querySelector('#'+active)?.classList.add('active'); t.querySelector(`.tab-btn[onclick="switchTab('${active}')"]`)?.classList.add('active'); }
            updateDOM(c.firstChild, t.firstChild) || (c.innerHTML = h);
        };
        const Mvu = window.Mvu || (window.parent && window.parent.Mvu) || (window.top && window.top.Mvu);
        if(Mvu) {
            if(Mvu.events) document.addEventListener(Mvu.events.VARIABLE_UPDATE_ENDED, e => render(e.detail.stat_data));
            (async ()=>{ try { if(typeof getChatMessages !== 'undefined') render((await getChatMessages(getCurrentMessageId()))[0]?.data?.stat_data); } catch(e){} })();
        } else setTimeout(init, 500);
    };
    if(typeof $ !== 'undefined') $(init); else document.addEventListener('DOMContentLoaded', init);
</script>
