    #gm-debug-wrapper {
        position: fixed; top: 10px; right: 15px; z-index: 99999;
        font-family: 'Segoe UI', 'Roboto', sans-serif; font-size: 13px; user-select: none;
        opacity: 0.2; transition: opacity 0.3s ease; pointer-events: none;
    }
    #gm-debug-wrapper:hover, #gm-debug-wrapper:has(.gm-panel.show) { opacity: 1; pointer-events: auto; }


    .gm-trigger {
        width: 42px; height: 42px; border-radius: 10px;
        background: var(--gm-bg); color: var(--gm-accent);
        display: flex; align-items: center; justify-content: center;
        cursor: pointer; pointer-events: auto;
        border: 1px solid rgba(122, 162, 247, 0.3);
        box-shadow: 0 4px 15px rgba(0,0,0,0.3);
        backdrop-filter: blur(8px); font-size: 18px; margin-left: auto; transition: transform 0.2s;
    }
    .gm-trigger:hover { transform: scale(1.1); color: #fff; background: var(--gm-accent); border-color: #fff; }


    .gm-panel {
        display: none; 
        position: absolute; top: 55px; right: 0;
        width: 340px; height: 600px;
        min-width: 300px; min-height: 300px;
        max-width: 90vw; max-height: 90vh;
        resize: both; overflow: hidden;
        background: var(--gm-bg);
        border: 1px solid var(--gm-border); border-radius: var(--gm-radius);
        box-shadow: 0 20px 60px rgba(0,0,0,0.6);
        backdrop-filter: blur(20px);
        transform-origin: top right;
        flex-direction: column;
