    .gm-panel.show { display: flex; animation: gmSlideIn 0.25s cubic-bezier(0.18, 0.89, 0.32, 1.28); }
    .gm-panel.maximized { width: 92vw !important; height: 92vh !important; resize: none; top: 10px; right: -10px; }
