<script>
    let _gmSnapshot = null;
    let _currentMvuData = null;
    const getDeep = (obj, path, def) => path.split('.').reduce((acc, part) => acc && acc[part], obj) ?? def;

    window.toggleGM = () => {
        const p = document.getElementById('gm-panel');
        if (p) {
            if (!p.classList.contains('show')) {
                p.style.display = 'flex'; 
                requestAnimationFrame(() => {
                    p.classList.add('show');
