            `).join('') || '<span style="opacity:0.5; font-style:italic;">文本445</span>';


            setInp('inp-hp', getDeep(d, '文本148.文本198.文本315.文本316', 0));
            setInp('inp-mp', getDeep(d, '文本148.文本198.文本320.文本316', 0));
