            const threatPanel = document.getElementById('panel-threat-forecast');
            if (threatPanel) {
                if (isIntermission) {
                    threatPanel.style.display = 'block';
                    const turnCount = getDeep(d, '文本296.文本405', 0);


                    const isFallen = getDeep(d, '文本148.文本198.文本56') === '文本58';
                    const panelTitleEl = document.getElementById('threat-panel-title');

                    if (isFallen) {
                        panelTitleEl.innerHTML = '<i class="fa-solid fa-crosshairs"></i> 文本454 (文本455)';
                        threatPanel.style.borderColor = 'var(--pleasure-color)';
                        threatPanel.style.borderLeftColor = 'var(--pleasure-color)';
                        threatPanel.querySelector('.gm-label').style.color = 'var(--pleasure-color)';
                    } else {
                        panelTitleEl.innerHTML = '<i class="fa-solid fa-radar"></i> 文本380 (文本381)';
                        threatPanel.style.borderColor = '#e0af68';
                        threatPanel.style.borderLeftColor = '#e0af68';
                        threatPanel.querySelector('.gm-label').style.color = '#e0af68';
                    }

                    setTxt('threat-turn-counter', `文本382: ${turnCount}/5 ${turnCount >= 5 ? '(Ready!)' : ''}`);


                    const preySelector = document.getElementById('fallen-prey-selector');
                    const targetType = getDeep(d, '文本135.文本136.文本349', '文本115');

                    const activeColor = isFallen ? 'var(--pleasure-color)' : '#e0af68'; 

                    preySelector.style.display = 'flex';

                    document.getElementById('prey-selector-label').innerText = isFallen ? '🎯 文本456:' : '🎯 文本457:';
                    document.getElementById('btn-prey-random').style.borderColor = (targetType==='文本115'||targetType==='文本384') ? activeColor : 'var(--gm-border)';
                    document.getElementById('btn-prey-monster').style.borderColor = targetType==='文本283' ? activeColor : 'var(--gm-border)';
                    document.getElementById('btn-prey-mg').style.borderColor = targetType==='文本281' ? activeColor : 'var(--gm-border)';


                    const themeArea = document.getElementById('threat-theme-area');
                    if (isFallen && targetType === '文本281') {
                        themeArea.style.display = 'none';
                    } else {
                        themeArea.style.display = 'block';
                        const t_themesRaw = getDeep(d, '文本135.文本136.文本140', []);
                        const t_validThemes = Array.isArray(t_themesRaw) ? t_themesRaw.filter(t => t !== '$__META_EXTENSIBLE__$') : [];
                        const t_mainTheme = t_validThemes[0] || '文本458';
                        const t_subTheme = t_validThemes[1] || null;

                        setTxt('threat-main-theme', t_mainTheme);
                        const subContainer = document.getElementById('threat-sub-options');
                        const subStatus = document.getElementById('threat-sub-status');

                        if (t_subTheme) {
                            subStatus.innerText = '[文本459]';
                            subStatus.style.color = 'var(--combat-color)';
                            subContainer.innerHTML = `<div class="theme-tag" style="border-color:var(--combat-color); color:var(--combat-color);">${t_subTheme}</div>`;
                        } else {
                            subStatus.innerText = '[文本460AI文本461]';
                            subStatus.style.color = 'var(--hp-color)';
                            const pool = getDeep(d, '文本296.Boss文本462', []).filter(t => t !== '$__META_EXTENSIBLE__$' && t !== t_mainTheme);
                            const shuffled = pool.sort(() => 0.5 - Math.random()).slice(0, 8);
                            subContainer.innerHTML = shuffled.map(t => `<div class="theme-tag" style="cursor:pointer;" onclick="lockThreatSubTheme('${t}')">${t}</div>`).join('');
                        }
                    }
                } else {
                    threatPanel.style.display = 'none';
                }
            }

            renderWorldNotes(d); 
        } catch (e) { console.error("[GM Render]", e); }
    };


    window.gm_update = async (path, value, mode = 'set') => {
        try {
            const Mvu = window.Mvu || window.parent?.Mvu || window.top?.Mvu;
            if (!Mvu) return;
            const mvuData = Mvu.getMvuData({ type: 'message', message_id: -1 });
            if (!mvuData) return;
            if (typeof _ !== 'undefined' && _.set) {
                if (mode === 'remove') _.unset(mvuData, path);
                else if (mode === 'add') { const old = _.get(mvuData, path) || 0; _.set(mvuData, path, Number(old) + Number(value)); }
                else _.set(mvuData, path, value);
            }
            await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: -1 });
            const cleanData = JSON.parse(JSON.stringify(mvuData.stat_data || mvuData));
            document.dispatchEvent(new CustomEvent(Mvu.events.VARIABLE_UPDATE_ENDED, { detail: { stat_data: cleanData }, bubbles: true }));
            setTimeout(renderGM, 50);
        } catch (e) { console.error("[GM Update]", e); }
    };

window.renderWorldNotes = (data) => {
    const notes = getDeep(data, '文本135.文本268', {});
    const container = document.getElementById('world-notes-list');
    if (!container) return;
    const entries = Object.entries(notes).filter(([k]) => k !== '$meta' && k !== '$__META_EXTENSIBLE__$');
    container.innerHTML = entries.map(([k, v]) => `
        <div style="background:rgba(255,255,255,0.03); padding:6px; border-radius:4px; border-left:2px solid var(--gm-accent); position:relative;">
