            <div style="font-size:0.8em; opacity:0.8;">${v}</div>
            <div style="position:absolute; top:4px; right:4px; display:flex; gap:5px;">
                <i class="fa-solid fa-pen" style="cursor:pointer; font-size:10px; opacity:0.5;" onclick="editNote('${k}')"></i>
                <i class="fa-solid fa-trash" style="cursor:pointer; font-size:10px; color:#f7768e;" onclick="gm_update('stat_data.文本135.文本268.${k}', null, 'remove')"></i>
            </div>
        </div>`).join('') || '<div style="text-align:center; opacity:0.5; font-size:0.8em;">文本463</div>';
};

window.toggleNoteEditor = () => {
