    window.injectTheme = async () => {
        const input = document.getElementById('new-theme-input');
        const val = input.value.trim();
        if(!val) return;
        const targetPath = document.getElementById('theme-target-label').innerText.includes("文本154") ? 'stat_data.文本135.文本154H文本155.文本140' : 'stat_data.文本135.文本136.文本140';
        let arr = getDeep(_currentMvuData, targetPath.replace('stat_data.', ''), []);
